oxy_webhelp_navlinks = {"support_access-d39536e1702":{"topics":[{"title":"Enabling support access","shortdesc":"<p class=\"shortdesc\">You can enable support access for an <span class=\"ph\">RSC<\/span> user account.<\/p>","href":"saas\/common\/enabling_support_access.html","attributes":{"data-id":"enabling_support_access"},"menu":{"hasChildren":false},"tocID":"enabling_support_access-d39536e1716","topics":[]},{"title":"Editing support access duration","shortdesc":"<p class=\"shortdesc\">A user with the Grant Own Support Access or Grant All Support Access permission can         increase the support access duration for an existing support access grant.<\/p>","href":"saas\/common\/editing_support_access.html","attributes":{"data-id":"editing_support_access"},"menu":{"hasChildren":false},"tocID":"editing_support_access-d39536e1730","topics":[]},{"title":"Revoking support access","shortdesc":"<p class=\"shortdesc\">A user with the Grant Own Support Access or Grant All Support Access permission can         revoke an existing support access grant.<\/p>","href":"saas\/common\/revoking_support_access.html","attributes":{"data-id":"revoking_support_access"},"menu":{"hasChildren":false},"tocID":"revoking_support_access-d39536e1741","topics":[]},{"title":"Viewing support access audit logs","shortdesc":"<p class=\"shortdesc\">A user with the View All Support Access permission can view and download the audit         log information of a support access instance.<\/p>","href":"saas\/common\/viewing_support_access_audit_logs.html","attributes":{"data-id":"viewing_support_access_audit_logs"},"menu":{"hasChildren":false},"tocID":"viewing_support_access_audit_logs-d39536e1752","topics":[]}]}};